// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }
    function testFuzz_property(uint256 amount) public {
        // Bound amount to a reasonable range to avoid overflow issues if any
        amount = bound(amount, 0, type(uint256).max);

        // Ensure owner can call AdjustDifficulty
        vm.prank(address(this));
        c.AdjustDifficulty(amount);

        // The general rule: the public getter currentDifficulty() returns the passed amount
        assertTrue(c.currentDifficulty() == amount);
    }
}

